do $release$ declare payload jsonb:='{"batch":"nl-scale-20261102-009","project":"hlvujbrmfdlrfxdjwsmb","actions":[{"ref":"a1","relation":"authors","key":{"open_library_id":"OL55662A"},"before":null,"after":{"name":"Peter Delpeut","open_library_id":"OL55662A","id":987308001}},{"ref":"w0","relation":"works","key":{"native_identity_key":"nlscale:20261102:ol:OL267613W"},"before":null,"after":{"title":"Astérix et les Normands","author_id":987303005,"first_publish_year":1966,"open_library_id":"OL267613W","cover_id":13137508,"source_type":"open_library","work_type":null,"native_identity_key":"nlscale:20261102:ol:OL267613W","id":987108001}},{"ref":"e0","relation":"editions","key":{"open_library_edition_id":"OL9097654M"},"before":null,"after":{"work_id":"@w0","open_library_edition_id":"OL9097654M","isbn_13":"9789032004071","isbn_10":null,"title":"Asterix en de Noormannen","language":"dut","publisher":"Dargaud Benelux/Oberon","id":987208001,"publish_date":null,"cover_id":13137508}},{"ref":"d0","relation":"catalog_work_descriptions","key":{"work_id":"@w0","language":"nl"},"before":null,"after":{"work_id":"@w0","language":"nl","bound_author_id":987303005,"text":"Normandiërs komen naar het Gallische dorp met een ongebruikelijke bedoeling: ze willen ontdekken wat angst is. De dorpsbewoners laten zich dankzij hun toverdrank nauwelijks intimideren. Een jonge bezoeker uit Lutetia reageert heel anders en trekt daardoor de aandacht van de vreemdelingen. Asterix en Obelix raken betrokken bij de botsing tussen stoere bezoekers en iemand die hun onverschrokkenheid niet deelt. Het album draait om een ontmoeting waarin dezelfde dreiging voor de betrokkenen een heel verschillende betekenis heeft.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.hachette.co.uk/titles/ren%C3%A9-goscinny-2/asterix-asterix-and-the-normans/9780752866222/","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["https://data.bibliothe