}],"review_status":"approved","reviewed_at":"2026-11-02T18:57:00.000Z","review_batch":"nl-scale-20261102-009"}},{"ref":"w6","relation":"works","key":{"native_identity_key":"nlscale:20261102:ol:OL22755879W"},"before":null,"after":{"title":"Met de kennis van toen","author_id":930300011,"first_publish_year":2012,"open_library_id":"OL22755879W","cover_id":12619345,"source_type":"open_library","work_type":null,"native_identity_key":"nlscale:20261102:ol:OL22755879W","id":987108007}},{"ref":"e6","relation":"editions","key":{"open_library_edition_id":"OL30731533M"},"before":null,"after":{"work_id":"@w6","open_library_edition_id":"OL30731533M","isbn_13":"9789023472124","isbn_10":null,"title":"Met de kennis van toen","language":"dut","publisher":"De Bezige Bij","id":987208007,"publish_date":null,"cover_id":12619345}},{"ref":"d6","relation":"catalog_work_descriptions","key":{"work_id":"@w6","language":"nl"},"before":null,"after":{"work_id":"@w6","language":"nl","bound_author_id":930300011,"text":"Rutger Bregman onderzoekt hoe het verleden wordt gebruikt in hedendaagse discussies. Politici en opiniemakers beroepen zich geregeld op de geschiedenis, maar hun vergelijkingen zijn niet vanzelfsprekend betrouwbaar. Het boek zoekt naar manieren waarop historische kennis wel tot inzicht kan leiden. Bregman brengt uiteenlopende maatschappelijke onderwerpen met vroegere gebeurtenissen en ideeën in verband. Daarmee stelt hij de vraag wat leren van geschiedenis kan betekenen en welke vertekeningen ontstaan wanneer het verleden vooral een argument voor het eigen gelijk wordt.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.debezigebij.nl/boek/met-de-kennis-van-toen/ebook/9789023469971/","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p338896708"],"reference":"new-work-dossier-readings-009.json#220","checked_at":"2026-11-02T18:57:00.000Z","note":"Original Dutch histor